import{c as t,Q as e,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"SetOrgShape","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetOrgShape","slug":"setorgshape"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/SetOrgShape.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/SetOrgShape.md"}'),l={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/SetOrgShape.md"};function p(r,a,i,d,o,g){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="setorgshape" tabindex="-1">SetOrgShape <a class="header-anchor" href="#setorgshape" aria-label="Permalink to &quot;SetOrgShape&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>设置Matmul计算原始完整的形状M、N、K，单位为元素个数。用于运行时修改shape，比如复用同一个Matmul对象，从不同的矩阵块取数据计算。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void SetOrgShape(int orgM, int orgN, int orgK)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void SetOrgShape(int orgM, int orgN, int orgKa, int orgKb, int orgKc = 0)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>orgM</td><td>输入</td><td>设置原始完整的形状M大小，单位为元素。 对于Ascend 950PR/Ascend 950DT，在使用MDL模板创建的Matmul对象调用本接口时，该参数用于设置GM或L1上完整的形状M大小，单位为元素。</td></tr><tr><td>orgN</td><td>输入</td><td>设置原始完整的形状N大小，单位为元素。 对于Ascend 950PR/Ascend 950DT，在使用MDL模板创建的Matmul对象调用本接口时，该参数用于设置GM或L1上完整的形状N大小，单位为元素。</td></tr><tr><td>orgK</td><td>输入</td><td>设置原始完整的形状K大小，单位为元素。原始完整形状Ka=Kb时可设置。 对于Ascend 950PR/Ascend 950DT，在使用MDL模板创建的Matmul对象调用本接口时，该参数用于设置GM或L1上完整的形状K大小，单位为元素。原始完整形状Ka=Kb时可设置。</td></tr><tr><td>orgKa</td><td>输入</td><td>设置矩阵A原始完整的形状Ka大小，单位为元素。 对于Ascend 950PR/Ascend 950DT，在使用MDL模板创建的Matmul对象调用本接口时，该参数用于设置GM或L1上完整的形状Ka大小，单位为元素。</td></tr><tr><td>orgKb</td><td>输入</td><td>设置矩阵B原始完整的形状Kb大小，单位为元素。 对于Ascend 950PR/Ascend 950DT，在使用MDL模板创建的Matmul对象调用本接口时，该参数用于设置GM或L1上完整的形状Kb大小，单位为元素。</td></tr><tr><td>orgKc</td><td>输入</td><td>设置输出C矩阵的N，单位为元素。需要输入B矩阵的N和输出C矩阵的N不一样时可设置，默认为0（即使用B矩阵的N，不进行修改）。</td></tr></tbody></table><div class="caution custom-block github-alert"><p class="custom-block-title">注意</p><p></p><ul><li>对于Ascend 950PR/Ascend 950DT上使用<a href="./MatmulConfig.html">MDL模板</a>创建的Matmul对象，L1上数据的形状与Tiling侧接口<a href="./../Matmul-Tiling侧接口/Matmul-Tiling类/SetOrgShape-87.html">SetOrgShape</a>中的orgMIn/orgNIn/orgKIn/orgKaIn/orgKbIn一致时，不必须调用此接口。</li><li>对于Ascend 950PR/Ascend 950DT上使用<a href="./MatmulConfig.html">MDL模板</a>创建的Matmul对象，L1上数据的形状与Tiling侧接口<a href="./../Matmul-Tiling侧接口/Matmul-Tiling类/SetOrgShape-87.html">SetOrgShape</a>中的orgMIn/orgNIn/orgKIn/orgKaIn/orgKbIn不一致时，必须调用本接口指定GM/L1上的orgM/orgN/orgK/orgKa/orgKb。 例如，使用<a href="./MatmulConfig.html">MDL模板</a>时，输入矩阵A在L1、输入矩阵B在GM的场景，L1上A的形状大小与Tiling侧原始的orgMIn/orgKIn/orgKaIn不一致时，调用SetOrgShape(orgM, orgN, orgK)/SetOrgShape(orgM, orgN, orgKa, orgKb)接口指定L1上A矩阵相关参数orgM/orgK/orgKa。</li></ul></div><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>本接口需要在SetTensorA接口、SetTensorB接口、SetBias接口及SetSingleShape接口前调用。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>设置矩阵原始完整的形状</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);</span></span>
<span class="line"><span>mm.SetTensorA(gm_a);</span></span>
<span class="line"><span>mm.SetTensorB(gm_b);</span></span>
<span class="line"><span>mm.SetBias(gm_bias);</span></span>
<span class="line"><span>mm.IterateAll(gm_c);</span></span>
<span class="line"><span>//  复用mm对象</span></span>
<span class="line"><span>mm.SetOrgShape(orgM, orgN, orgK);</span></span>
<span class="line"><span>mm.SetTensorA(gm_a1);</span></span>
<span class="line"><span>mm.SetTensorB(gm_b1);</span></span>
<span class="line"><span>mm.SetBias(gm_bias1);</span></span>
<span class="line"><span>mm.IterateAll(gm_c1);</span></span></code></pre></div></li><li><p>对于Ascend 950PR/Ascend 950DT上使用<a href="./MatmulConfig.html">MDL模板</a>的Matmul对象，设置GM或L1上完整的形状</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);</span></span>
<span class="line"><span>for (int m = 0; m &lt; mIter_; m++) {</span></span>
<span class="line"><span>     for (int n = 0; n &lt; nIter_; n++) {</span></span>
<span class="line"><span>          for (int k = 0; k &lt; kIter_; k++) {</span></span>
<span class="line"><span>               // 复用mm，指定A在L1和B在GM上的shape</span></span>
<span class="line"><span>               mm.SetOrgShape(alignedSingleM, tiling.N, alignedSingleK, tiling.Kb, tiling.N);</span></span>
<span class="line"><span>               mm.SetSingleShape(curBaseM, curBaseN, curBaseK);</span></span>
<span class="line"><span>               mm.SetTensorA(tscm_a[offset_a]); // Set aMatrix tscm input</span></span>
<span class="line"><span>               mm.SetTensorB(gm_b[offset_b]);</span></span>
<span class="line"><span>               mm.SetBias(gm_bias[offset_bias]);</span></span>
<span class="line"><span>               mm.Iterate(k != 0);</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>            matmulObj.GetTensorC(gm_c[offset_c]);</span></span>
<span class="line"><span>     }</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ul>`,18)])])}const m=t(l,[["render",p]]);export{h as __pageData,m as default};
